import sys
import os
import requests

def get_bearer_token():
    if 'NOTE_API_TOKEN' in os.environ and os.environ['NOTE_API_TOKEN']:
        return os.environ['NOTE_API_TOKEN']
    else:
        line = sys.stdin.readline().rstrip('\n')
        return line

def main():
    if len(sys.argv) != 3:
        print("Usage: python note_uploader.py <file_path> <title>", file=sys.stderr)
        sys.exit(1)

    file_path = sys.argv[1]
    title = sys.argv[2]

    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            body = file.read()
    except IOError as e:
        print(f"Error reading file: {e}", file=sys.stderr)
        sys.exit(1)

    bearer_token = get_bearer_token()

    headers = {
        'Authorization': f'Bearer {bearer_token}',
        'Content-Type': 'application/json'
    }

    data = {
        'title': title,
        'body': body
    }

    response = requests.post('https://api.notes.example.com/v1/notes', json=data, headers=headers)

    if response.status_code == 201:
        print(response.json().get('url', ''))
        sys.exit(0)
    else:
        print(response.text, file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
